class Solution {
public:
    bool sequenceReconstruction(vector<int>& nums, vector<vector<int>>& sequences) {
        int n = static_cast<int>(nums.size());
        vector<unordered_set<int>> edges(n + 1);
        vector<int> indegree(n + 1, 0);
        vector<bool> seen(n + 1, false);
        for (const auto& sequence : sequences) {
            for (int value : sequence) {
                if (value < 1 || value > n) {
                    return false;
                }
                seen[value] = true;
            }
            for (int i = 1; i < static_cast<int>(sequence.size()); ++i) {
                int u = sequence[i - 1], v = sequence[i];
                if (edges[u].insert(v).second) {
                    ++indegree[v];
                }
            }
        }
        for (int value = 1; value <= n; ++value) {
            if (!seen[value]) {
                return false;
            }
        }
        queue<int> ready;
        for (int value = 1; value <= n; ++value) {
            if (indegree[value] == 0) {
                ready.push(value);
            }
        }
        int index = 0;
        while (!ready.empty()) {
            if (ready.size() != 1 || nums[index++] != ready.front()) {
                return false;
            }
            int u = ready.front();
            ready.pop();
            for (int v : edges[u]) {
                if (--indegree[v] == 0) {
                    ready.push(v);
                }
            }
        }
        return index == n;
    }
};
